use rand::Rng;
use std::time::Duration;

pub struct Backoff { attempt: u32, base: Duration, cap: Duration }

impl Backoff {
    pub fn new(base: Duration, cap: Duration) -> Self { Self { attempt: 0, base, cap } }
    pub fn reset(&mut self) { self.attempt = 0; }
    /// Full jitter: sleep = random(0, min(cap, base * 2^attempt))
    pub fn next_delay(&mut self) -> Duration {
        let exp = self.base.saturating_mul(1u32 << self.attempt.min(16));
        let ceiling = exp.min(self.cap);
        self.attempt += 1;
        Duration::from_millis(rand::thread_rng().gen_range(0..=ceiling.as_millis() as u64))
    }
}

