let mut backoff = Backoff::new(Duration::from_millis(500), Duration::from_secs(60));
loop {
    match eventloop.poll().await {
        Ok(Event::Incoming(Packet::ConnAck(_))) => { backoff.reset(); info!("mqtt connected"); }
        Ok(_) => {}
        Err(e) => {
            let d = backoff.next_delay();
            warn!(error = %e, delay_ms = d.as_millis() as u64, "mqtt disconnected, retrying");
            tokio::time::sleep(d).await;
        }
    }
}

