#[test]
fn delays_never_exceed_cap() {
    let mut b = Backoff::new(Duration::from_millis(500), Duration::from_secs(60));
    for _ in 0..50 { assert!(b.next_delay() <= Duration::from_secs(60)); }
}
#[test]
fn reset_restarts_growth() {
    let mut b = Backoff::new(Duration::from_millis(500), Duration::from_secs(60));
    for _ in 0..10 { b.next_delay(); }
    b.reset();
    assert!(b.next_delay() <= Duration::from_millis(500));
}
